#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up everything the test agent workflow needs that only a repo admin can
# do: the GitHub App the workflow pushes the agent's commits with
# (docs/adr/0002), its credentials, the Claude token, branch protection on
# main and the opt-out label.

TOTAL_STAGES=7

die() { printf '%s%s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

[[ -t 0 ]] || die "This wizard is interactive: run it in a terminal."
cd "$(git rev-parse --show-toplevel)"
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  die "This wizard needs the GitHub CLI, logged in as a repo admin: gh auth login"
fi

REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null) ||
  die "Couldn't tell which GitHub repo this is. Run: gh repo set-default"
# Every gh call below, the library's set_secret/set_var included, targets this repo.
export GH_REPO="$REPO"
OWNER=${REPO%/*}
REPO_NAME=${REPO#*/}
APP_NAME="${REPO_NAME}-test-agent"
if [[ "$(gh api "users/$OWNER" -q .type 2>/dev/null || true)" == Organization ]]; then
  APPS_URL="https://github.com/organizations/$OWNER/settings/apps"
else
  APPS_URL="https://github.com/settings/apps"
fi
# The CI job names in .github/workflows/ci.yml; renaming a job there means
# updating this. 15368 is the GitHub Actions app, so no other app (the test
# agent's included, which has checks:write) can satisfy them.
REQUIRED_CHECKS='[{"context": "backend", "app_id": 15368}, {"context": "frontend", "app_id": 15368}]'

has_secret() { [[ -n "$(gh secret list --json name -q ".[] | select(.name == \"$1\") | .name")" ]]; }
has_var()    { [[ -n "$(gh variable list --json name -q ".[] | select(.name == \"$1\") | .name")" ]]; }
is_pem()     { [[ -f "$1" ]] && grep -q -- '-----BEGIN .*PRIVATE KEY-----' "$1"; }
ok()         { printf '  %s✓ %s%s %s\n' "$GREEN" "$1" "$RESET" "$2"; }

# keep_existing "what": succeeds when the human wants to keep a value already on the repo.
keep_existing() {
  note "$1 is already set on $REPO."
  ! confirm "Replace it?"
}

banner "Test agent setup for $REPO"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: create"
say "The workflow pushes the test agent's commits with a GitHub App token, so CI runs on them."
if has_var TEST_AGENT_APP_ID && ! confirm "An app is already configured (TEST_AGENT_APP_ID is set). Create a new one anyway?"; then
  note "Keeping the existing app."
else
  say "The form opens prefilled: name, homepage, no webhook, and the three permissions."
  open_url "$APPS_URL/new?name=${APP_NAME}&description=Pushes+unit+tests+written+by+the+test+agent+to+PRs+in+${REPO}&url=https://github.com/${REPO}&public=false&webhook_active=false&contents=write&pull_requests=write&checks=write"
  step "Check the name. App names are global, so add a suffix if it's taken."
  step "Webhook: leave 'Active' unchecked."
  step "Repository permissions should read: Checks, Contents and Pull requests 'Read and write' (Metadata 'Read-only' is mandatory)."
  step "Where can this GitHub App be installed? 'Only on this account'."
  step "Click 'Create GitHub App'. Stay on the page it opens."
fi
pause "Done? Press Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: App ID → variable"
if has_var TEST_AGENT_APP_ID && keep_existing "Variable TEST_AGENT_APP_ID"; then
  note "Keeping TEST_AGENT_APP_ID."
else
  step "On the app's 'General' page, the 'About' section shows 'App ID' (a number)."
  step "Not there? Open $APPS_URL → 'Edit' next to the app."
  TEST_AGENT_APP_ID=""
  until [[ "$TEST_AGENT_APP_ID" =~ ^[0-9]+$ ]]; do
    ask TEST_AGENT_APP_ID "Paste the App ID:"
    [[ "$TEST_AGENT_APP_ID" =~ ^[0-9]+$ ]] || warn "The App ID is a number, e.g. 1234567."
  done
  set_var TEST_AGENT_APP_ID "$TEST_AGENT_APP_ID"
fi
pause "Press Enter for the next stage"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: private key → secret"
if has_secret TEST_AGENT_APP_PRIVATE_KEY && keep_existing "Secret TEST_AGENT_APP_PRIVATE_KEY"; then
  note "Keeping TEST_AGENT_APP_PRIVATE_KEY."
else
  step "On the same 'General' page, scroll to 'Private keys' → 'Generate a private key'."
  step "Your browser downloads a .pem file."
  pause "Downloaded? Press Enter"
  newest_pem=$(ls -t "$HOME"/Downloads/*.private-key.pem 2>/dev/null | head -n1 || true)
  pem_path=""
  until is_pem "$pem_path"; do
    if [[ -n "$newest_pem" ]]; then
      printf '  %sPath to the .pem:%s %s[Enter uses %s]%s ' "$BOLD" "$RESET" "$DIM" "$newest_pem" "$RESET"
    else
      printf '  %sPath to the .pem:%s ' "$BOLD" "$RESET"
    fi
    read -r pem_path || true
    [[ -z "$pem_path" ]] && pem_path="$newest_pem"
    pem_path="${pem_path/#\~/$HOME}"
    is_pem "$pem_path" || warn "That isn't a private key file. Try again."
  done
  set_secret TEST_AGENT_APP_PRIVATE_KEY "$(cat "$pem_path")"
  if confirm "Delete $pem_path now? GitHub keeps no copy, but you can generate a new key any time."; then
    rm -f "$pem_path"
    ok deleted "$pem_path"
  else
    warn "Keep $pem_path somewhere safe, or delete it: it can push to $REPO."
  fi
fi
pause "Press Enter for the next stage"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub App: install on $REPO_NAME only"
say "Already installed on $REPO_NAME? Just press Enter."
step "In the app's left sidebar, click 'Install App' → 'Install' next to your account."
step "Choose 'Only select repositories' and pick $REPO_NAME. Nothing else."
step "Click 'Install'."
pause "Installed? Press Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Claude: OAuth token → secret"
if has_secret CLAUDE_CODE_OAUTH_TOKEN && keep_existing "Secret CLAUDE_CODE_OAUTH_TOKEN"; then
  note "Keeping CLAUDE_CODE_OAUTH_TOKEN."
else
  say "The token is tied to your Claude subscription and lasts about a year."
  if command -v claude >/dev/null 2>&1; then
    step "Running 'claude setup-token'. Sign in in the browser it opens."
    step "When it prints the token (sk-ant-oat01-…), copy it."
    pause "Press Enter to run it"
    claude setup-token || warn "claude setup-token exited with an error. You can run it in another terminal."
  else
    warn "The claude CLI isn't installed here."
    step "Run 'claude setup-token' wherever Claude Code is installed, and copy the token it prints."
  fi
  CLAUDE_CODE_OAUTH_TOKEN=""
  until [[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]]; do
    ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (hidden):"
  done
  [[ "$CLAUDE_CODE_OAUTH_TOKEN" == sk-ant-oat* ]] || warn "That doesn't start with sk-ant-oat. Storing it anyway."
  set_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
  note "The token is in your terminal scrollback. Clear it when you're done."
fi
pause "Press Enter for the next stage"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Protect main"
say "Branch protection on main in $REPO:"
step "Require a pull request (0 approvals, since this is a one-person repo)."
step "Require the ci checks backend and frontend, reported by GitHub Actions, to pass."
step "Require the branch to be up to date with main before merging."
step "Apply the rules to admins too, so main only changes through PRs."
note "The workflow never pushes the test agent's commits to main, so the app needs no bypass."
if gh api "repos/$REPO/branches/main/protection" >/dev/null 2>&1; then
  warn "main is already protected. This replaces its current rules."
fi
if confirm "Apply this protection to main?"; then
  if gh api -X PUT "repos/$REPO/branches/main/protection" --input - >/dev/null <<JSON
{
  "required_status_checks": { "strict": true, "checks": $REQUIRED_CHECKS },
  "enforce_admins": true,
  "required_pull_request_reviews": { "required_approving_review_count": 0 },
  "restrictions": null
}
JSON
  then
    ok protected main
  else
    SKIPPED+=("Branch protection on main: Settings → Branches on $REPO")
    warn "GitHub rejected the request. Set it under Settings → Branches."
  fi
else
  SKIPPED+=("Branch protection on main")
  note "Skipped."
fi
pause "Press Enter for the next stage"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Label: skip-test-agent"
say "Labelling a PR skip-test-agent stops the test agent from running on it."
if gh api "repos/$REPO/labels/skip-test-agent" >/dev/null 2>&1; then
  note "The label already exists. Leaving it as it is."
elif gh label create skip-test-agent --color ededed \
  --description "Don't run the test agent on this PR" >/dev/null; then
  ok created "label skip-test-agent"
else
  SKIPPED+=("Label skip-test-agent: gh label create skip-test-agent")
  warn "Couldn't create the label."
fi
pause "Press Enter to finish"

finish
